"""Discover original Virtual Life v6b NPC stock generated by npc_v6b.py.

These are REAL v6b sprites rendered by the native shared engine; no new
character design and no retargeting are performed. Generated output exists
only in the build workspace and the public static catalog, not source Git.
"""
from __future__ import annotations
import json
from pathlib import Path
from PIL import Image

def add_native_npcs(root, media, actions, save_walk_preview,
                    save_expression_previews, available_actions, updated_timestamp,
                    repo_url):
    import sys
    tools = root / "chars-iso" / "v6b" / "tools"
    if str(tools) not in sys.path:
        sys.path.insert(0, str(tools))
    import npc_v6b as nv
    out = root / "chars-iso" / "v6b" / "live" / "npc"
    source = root / "chars-iso" / "v6b" / "tools" / "npc_v6b.py"
    records = []
    for name in sorted(nv.NPCS):
        sheet = out / (name + "_v6b_sheet.png")
        if not sheet.exists():
            raise FileNotFoundError(f"Native NPC not generated: {name}. Run npc_v6b.py first.")
        with Image.open(sheet) as src:
            if src.mode != "RGBA" or src.size != (384, 4928):
                raise ValueError(f"Invalid native character sheet {sheet}: {src.size} {src.mode}")
        slug = "native_" + name
        walk = media / (slug + "-walk.gif")
        poster = media / (slug + "-poster.png")
        save_walk_preview(sheet, walk, poster, 0, 6)
        dst = media / (slug + "-sheet.png")
        dst.write_bytes(sheet.read_bytes())
        with Image.open(sheet) as im:
            im.crop((0, 4 * 112, 64, 5 * 112)).save(media / (slug + "-thumb.png"))
        overlays = sorted(out.glob(name + "_v6b_f*.png"))
        data = {
            "sprites": [p.name for p in overlays],
            "row_starts": dict(nv.lv.ROWMAP),
            "rows": 44,
            "idle_frames": 4,
            "walk_frames": 6
        }
        faces = save_expression_previews(out, data, sheet, media, name)
        # Native npc_v6b explicitly draws all of these ROWMAP action rows,
        # but they remain 'generator preview' until the owner approves.
        # Exclude custom/unbuilt motions like Press Button or Pick Up.
        cfg = {
            "approved_native_actions": [a["id"] for a in actions
                if a["type"] == "native_row" and a["row"] in nv.lv.ROWMAP],
        }
        # Legacy importer uses a neutral, read-only adapter to the genuine
        # engine rows instead of requiring private motions.json files.
        bindings = []
        for action in actions:
            row = nv.lv.ROWMAP.get(action.get("row", "")) if action["type"] == "native_row" else None
            bindings.append({
                "id":action["id"], "name":action["label"], "category":action["category"],
                "frames":action["frames"],"frame_ms":action["frame_ms"],"loop":action["loop"],
                "available":row is not None,"source":"native" if row is not None else "",
                "reason":"" if row is not None else "NEEDS CHARACTER RIG",
                **({"row":row} if row is not None else {})
            })
        records.append({
            "id":slug,"name":name.replace("_"," ").upper(),"type":"npc",
            "origin":"virtual-life/native-v6b","asset_status":"generated_preview",
            "description":"Original Virtual Life NPC / native v6b generator preview",
            "outfit":"","hairstyle":"","walk":"media/"+walk.name,
            "poster":"media/"+poster.name,"thumbnail":"media/"+slug+"-thumb.png",
            "sheet":"media/"+dst.name,"folder_url":repo_url+"/tree/main/chars-iso/v6b/tools",
            "source_url":repo_url+"/blob/main/chars-iso/v6b/tools/npc_v6b.py",
            "timestamp":updated_timestamp(source),"frame_size":"64 × 112",
            "walk_frames":6,"idle_frames":4,"row_starts":data["row_starts"],
            "expressions":faces,"motions":bindings,
        })
    # The primary playable avatar also belongs to the character library,
    # not just NPCs. Its sheet and expressions are built by live_v6b.py.
    player_folder = root / "chars-iso" / "v6b" / "live"
    player_sheet = player_folder / "ichsan_v6b_sheet.png"
    if not player_sheet.is_file():
        raise FileNotFoundError("Original Ichsan player sprite missing after v6b render")
    with Image.open(player_sheet) as im:
        if im.mode != "RGBA" or im.size != (384, 4928):
            raise ValueError("Invalid native player 384x4928 RGBA sheet")
    name = "ichsan"
    player_data = {
        "row_starts": dict(nv.lv.ROWMAP),
        "sprites": [p.name for p in sorted(player_folder.glob("ichsan_v6b_f*.png"))],
        "rows": 44,
    }
    player_walk = media / "ichsan-walk.gif"
    player_poster = media / "ichsan-poster.png"
    save_walk_preview(player_sheet, player_walk, player_poster, 0, 6)
    (media/"ichsan-sheet.png").write_bytes(player_sheet.read_bytes())
    with Image.open(player_sheet) as im:
        im.crop((0,448,64,560)).save(media/"ichsan-thumb.png")
    player_faces = save_expression_previews(player_folder,player_data,player_sheet,media,name)
    player_motions = []
    for action in actions:
        row = nv.lv.ROWMAP.get(action.get("row","")) if action["type"] == "native_row" else None
        player_motions.append({
            "id":action["id"],"name":action["label"],"category":action["category"],
            "frames":action["frames"],"frame_ms":action["frame_ms"],
            "loop":action["loop"],"available":row is not None,
            "source":"native" if row is not None else "",
            "reason":"" if row is not None else "NEEDS CHARACTER RIG",
            **({"row":row} if row is not None else {})
        })
    records.append({
        "id":"ichsan","name":"ICHSAN","type":"player",
        "origin":"virtual-life/live-v6b","asset_status":"generated_preview",
        "description":"Original Virtual Life player avatar / game-native v6b rig",
        "outfit":"","hairstyle":"","walk":"media/ichsan-walk.gif",
        "poster":"media/ichsan-poster.png","thumbnail":"media/ichsan-thumb.png",
        "sheet":"media/ichsan-sheet.png",
        "folder_url":repo_url+"/tree/main/chars-iso/v6b/live/chars",
        "source_url":repo_url+"/blob/main/chars-iso/v6b/tools/live_v6b.py",
        "timestamp":updated_timestamp(root/"chars-iso/v6b/live/chars/ichsan.json"),
        "frame_size":"64 × 112","walk_frames":6,"idle_frames":4,
        "row_starts":player_data["row_starts"],
        "expressions":player_faces,"motions":player_motions,
    })
    return records
